        h=1+drows(stem)
        corner=2+( (i+1)%3 )
        for _ in range(h): rows.append([0]*7)
        r0=len(rows)-h
        # arm
        d=drows(bar)
        if bar_slot==0:
            for k in range(d): rows[r0][corner+k]=bar[0][0]
        else:
            for k in range(d): rows[r0][corner-k]=bar[0][0]
        # stem below corner
        for k in range(1,drows(stem)+1):
            rows[r0+k][corner]=stem[0][0]
    return rows
